import os
import torch


class Config:
    """
    Configuration class for the Multi-Instance Attention-Pooled 2.5D Network.
    Centralizes all hyperparameters, file paths, and compute settings.
    """

    # --------------------------------------------------------------------------
    # Paths and Directories
    # --------------------------------------------------------------------------
    INPUT_DIR = "./input"
    TRAIN_DIR = os.path.join(INPUT_DIR, "train")
    TEST_DIR = os.path.join(INPUT_DIR, "test")

    # Metadata generated by the provided script
    METADATA_DIR = "./metadata"
    TRAIN_METADATA = os.path.join(METADATA_DIR, "train.csv")
    VAL_METADATA = os.path.join(METADATA_DIR, "val.csv")
    TEST_METADATA = os.path.join(METADATA_DIR, "test.csv")

    # Working directory for caching and model checkpoints
    # Specific to 'idea_5' as per the solution design
    WORKING_DIR = "./working/idea_6"
    os.makedirs(WORKING_DIR, exist_ok=True)

    # Submission output
    SUBMISSION_DIR = "./submission"
    os.makedirs(SUBMISSION_DIR, exist_ok=True)
    SUBMISSION_PATH = os.path.join(SUBMISSION_DIR, "submission.csv")

    # --------------------------------------------------------------------------
    # Data Processing Hyperparameters
    # --------------------------------------------------------------------------
    # Image resolution
    IMG_SIZE = 256

    # Multi-Instance Learning (MIL) Settings
    # We select the single best candidate region based on FLAIR intensity
    NUM_INSTANCES = 1

    # Stacking Logic (2.5D)
    # We take a stack of slices around the peak.
    # Stride 5 maximizes z-axis context without excessive redundancy.
    STACK_STRIDE = 5
    SLICES_PER_MODALITY = 3

    # Modalities to use
    MODALITIES = ["FLAIR", "T1w", "T1wCE", "T2w"]

    # Input Channels Calculation
    # 4 modalities * 3 slices per modality = 12 channels total input
    IN_CHANNELS = len(MODALITIES) * SLICES_PER_MODALITY

    # --------------------------------------------------------------------------
    # Model Architecture
    # --------------------------------------------------------------------------
    BACKBONE = "efficientnet_b0"
    NUM_CLASSES = 1

    # Grouped Convolutions for the first layer to maintain modality isolation
    # 12 input channels / 4 groups = 3 channels per group (RGB-like structure per modality)
    GROUPS = 4

    # --------------------------------------------------------------------------
    # Training Hyperparameters
    # --------------------------------------------------------------------------
    SEED = 42

    # Batch size: A100 40GB allows for a decent batch size even with MIL
    # Effective batch size = BATCH_SIZE * NUM_INSTANCES images processed per step
    BATCH_SIZE = 16

    NUM_EPOCHS = 15

    # Optimization
    LEARNING_RATE = 3e-4

    # Aggressive weight decay to prevent overfitting on small dataset (Cite 00011)
    WEIGHT_DECAY = 1e-2

    # Early Stopping
    EARLY_STOPPING_PATIENCE = 5

    # --------------------------------------------------------------------------
    # Compute
    # --------------------------------------------------------------------------
    NUM_WORKERS = 4
    DEVICE = "cuda" if torch.cuda.is_available() else "cpu"
